-- ============================================================
-- SEED EXT 6: Módulo 07 — Present Perfect (ex 214-300)
-- Tópicos: relevância atual de ações passadas, just/already/yet,
-- since/for, PP vs past simple, PP passivo, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: PP para eventos recentes com relevância atual
  (cid,71,214,'gap_fill','_____ (the/committee) _____ (issue) _____ formal _____ (warning) to _____ (the) _____ member _____ state and _____ (set) _____ a _____ sixty-day _____ deadline for _____ compliance — _____ (the) _____ government _____ must _____ now _____ (demonstrate) that _____ (it) _____ (take) _____ concrete _____ steps.','The / committee / has issued / a / formal / warning / the / member / state / has set / a / sixty-day / the / government / demonstrate / it / has taken / concrete / steps',NULL,'PP ''has issued/set/taken'' = recent past with direct current implications.','medium'),
  (cid,71,215,'gap_fill','_____ (the/research) _____ (change) _____ our _____ understanding of _____ (the) _____ mechanism — we _____ now _____ (know) that _____ (the) _____ earlier _____ model _____ (not/capture) _____ (the) _____ full _____ complexity of _____ (what) _____ (happen) at _____ (the) _____ cellular _____ level.','The / research / has changed / our / understanding / the / mechanism / now / know / the / earlier / model / did not capture / the / full / complexity / what / happens / the / cellular / level',NULL,'PP ''has changed'' (current relevance) + PS ''did not capture'' (completed past discovery).','hard'),
  (cid,71,216,'gap_fill','Several _____ (key) _____ (assumption) on which _____ (the) _____ policy _____ (base/passive) _____ (prove) _____ (flawed) — _____ (this) _____ (call into question) not just _____ (this) _____ specific _____ measure but _____ (the) _____ broader _____ framework of _____ which _____ it _____ (form) a _____ part.','key / assumptions / the / policy / was based / have proved / flawed / this / has called into question / not / this / specific / measure / the / broader / framework / which / forms / a / part',NULL,'PP ''have proved/has called into question'' for past findings with ongoing implications.','hard'),
  (cid,71,217,'gap_fill','_____ markets _____ (react) _____ negatively to _____ (the) _____ announcement — _____ (the) _____ index _____ (fall) by _____ more _____ than _____ three _____ percent since _____ (the) _____ news _____ (break) and _____ (investor) _____ (express) _____ serious _____ concerns about _____ (the) _____ sustainability of _____ (the) _____ current _____ approach.','Markets / have reacted / negatively / the / announcement / the / index / has fallen / more / than / three / percent / since / the / news / broke / investors / have expressed / serious / concerns / the / sustainability / the / current / approach',NULL,'PP ''have reacted/has fallen/have expressed'' since news broke for market response.','medium'),
  (cid,71,218,'gap_fill','_____ (the/government) _____ (not/yet/respond) to _____ (the) _____ opposition''s _____ demands and _____ (the/clock/tick) — _____ (the) _____ deadline _____ (set/passive) by _____ (the) _____ mediators _____ (pass) in _____ less than _____ forty-eight _____ hours.','The / government / has not yet responded / the / opposition''s / demands / the clock is ticking / the / deadline / set / the / mediators / will pass / in / less / than / forty-eight / hours',NULL,'PP ''has not yet responded'' + current PC ''is ticking'' + future ''will pass.''','medium'),
  (cid,71,219,'gap_fill','_____ (the/evidence) _____ (accumulate) _____ (to) _____ (the) _____ point where _____ it _____ (no longer/possible/be) to _____ (dismiss) _____ (the) _____ findings as _____ outliers — _____ (a) _____ critical _____ mass of _____ (replication) _____ (now/establish) _____ (the) _____ robustness of _____ (the) _____ original _____ result.','The / evidence / has accumulated / to / the / point / where / it / is no longer possible / dismiss / the / findings / as / a / critical / mass / replications / has now established / the / robustness / the / original / result',NULL,'PP ''has accumulated/established'' for evidence reaching critical mass with current implication.','hard'),
  (cid,71,220,'gap_fill','_____ (the/organisation) _____ (undergo) _____ significant _____ restructuring over _____ (the) _____ past _____ three _____ years — _____ (it) _____ (eliminate) _____ three _____ layers of _____ management, _____ (consolidate) _____ operations across _____ (four) _____ regional _____ hubs, and _____ (achieve) _____ cost _____ savings _____ that _____ (exceed) _____ initial _____ projections.','The / organisation / has undergone / significant / restructuring / the / past / three / years / it / has eliminated / three / layers / management / consolidated / operations / four / regional / hubs / achieved / cost / savings / have exceeded / initial / projections',NULL,'PP ''has undergone/eliminated/consolidated/achieved/exceeded'' for three-year restructuring summary.','hard'),
  (cid,71,221,'gap_fill','Nothing _____ (change) substantively since _____ (the) _____ last _____ report — _____ (the) _____ commitments _____ (make/passive) then _____ (not/honor/passive) and _____ (the) _____ conditions that _____ (give) _____ rise to _____ (the) _____ problem _____ (persist).','has changed / the / last / report / the / commitments / made / have not been honoured / the / conditions / gave / rise / the / problem / persist',NULL,'PP ''has changed/have not been honoured'' + PS ''gave'' + PS ''persist'' for unchanged situation.','hard'),
  (cid,71,222,'gap_fill','_____ (the/debate) _____ (now/move) beyond _____ (whether) action _____ (necessary/be) — _____ consensus on _____ that _____ (emerge) — to _____ (the) _____ more _____ difficult _____ questions of _____ what _____ kind of _____ action, _____ at _____ what _____ scale, and _____ (who) _____ (bear) _____ (the) _____ costs.','The / debate / has now moved / beyond / whether / action / is necessary / a / consensus / on / has emerged / to / the / more / difficult / questions / what / kind / action / what / scale / who / bears / the / costs',NULL,'PP ''has moved/emerged'' = progress to next stage; PS ''bears'' = ongoing question.','hard'),

  -- BLOCK 72: PP com just, already, yet, still
  (cid,72,223,'gap_fill','_____ (the/panel) _____ (just/publish) _____ its _____ findings, and _____ reactions _____ (already/begin) to _____ pour _____ in from _____ (stakeholder) across _____ (the) _____ sector who _____ (wait) for _____ (this) _____ assessment for _____ months.','The / panel / has just published / its / findings / reactions / have already begun / pour / in / stakeholders / across / the / sector / have been waiting / for / this / assessment / for / months',NULL,'''Has just published'' + ''have already begun'' + ''have been waiting'' for rapid response to new report.','medium'),
  (cid,72,224,'gap_fill','_____ (the/minister) _____ (not/yet/address) _____ (the) _____ substance of _____ (the) _____ allegations and _____ (the/opposition) _____ (already/call) for _____ (a) _____ formal _____ parliamentary _____ inquiry — _____ (the) _____ government _____ (still/not/clarify) its _____ position on _____ whether _____ (it) _____ (support) such _____ (a) _____ process.','The / minister / has not yet addressed / the / substance / the / allegations / the opposition / has already called / a / formal / parliamentary / inquiry / the / government / has still not clarified / its / position / on / whether / it / would support / such / a / process',NULL,'''Has not yet addressed/clarified'' + ''has already called'' for political standoff.','hard'),
  (cid,72,225,'gap_fill','_____ (the/agency) _____ (already/approve) _____ (the) _____ first _____ tranche of _____ funding but _____ (not/yet/disburse) it — _____ (the) _____ remaining _____ (condition) _____ (still/meet/passive/not), and _____ (it) _____ (unclear/be) when _____ they _____ (will).','The / agency / has already approved / the / first / tranche / funding / has not yet disbursed / the / remaining / conditions / have still not been met / it / is unclear / when / they / will be',NULL,'''Has already approved'' + ''has not yet disbursed'' + ''have not been met'' for funding approval vs disbursement gap.','hard'),
  (cid,72,226,'multiple_choice','Which sentence MOST CORRECTLY uses ''already'' with the present perfect in a formal context?','The secretariat has already circulated the draft agenda and is awaiting comments from member states.','["The secretariat already circulated the draft agenda.","The secretariat has already circulated the draft agenda and is awaiting comments from member states.","The secretariat has circulated the draft agenda already, members states are waiting.","Already the secretariat circulated the draft agenda."]','''Has already circulated'' = PP + already (action completed before expected time); ''is awaiting'' = PC for ongoing.','easy'),
  (cid,72,227,'gap_fill','_____ (the/results) _____ (not/yet/confirm/passive) by _____ (the) _____ independent _____ review _____ panel, but _____ (the) _____ preliminary _____ assessment _____ (already/suggest) that _____ (the) _____ findings _____ (likely/hold/passive).','The / results / have not yet been confirmed / the / independent / review / panel / the / preliminary / assessment / has already suggested / that / the / findings / will likely be upheld',NULL,'''Have not yet been confirmed'' (PP passive) + ''has already suggested'' for phased review process.','medium'),
  (cid,72,228,'gap_fill','Three _____ years _____ (pass) since _____ (the) _____ initiative _____ (launch/passive) and _____ (it) _____ (still/not/deliver) _____ on _____ its _____ core _____ (promise) — a _____ record that _____ (justify) _____ serious _____ (question) about _____ (whether) _____ (the) _____ approach _____ (fundamentally/sound/be).','Three / years / have passed / the / initiative / was launched / it / has still not delivered / on / its / core / promises / a / record / justifies / serious / questions / whether / the / approach / is fundamentally sound',NULL,'''Have passed/not delivered'' + PS ''justifies/is'' for time-elapsed accountability assessment.','hard'),
  (cid,72,229,'gap_fill','_____ (the/court) _____ (already/rule) on _____ (the) _____ procedural _____ (question) — _____ judgment _____ (issue/passive) last _____ week _____ (clarify) _____ that _____ (the) _____ more _____ substantive _____ hearing _____ (schedule/passive) for _____ next _____ month _____ (proceed) as _____ planned.','The / court / has already ruled / the / procedural / question / the / judgment / issued / last / week / clarified / that / the / more / substantive / hearing / scheduled / for / next / month / will proceed / as / planned',NULL,'''Has already ruled'' + PS ''issued/clarified'' + future ''will proceed'' for legal process sequencing.','hard'),
  (cid,72,230,'gap_fill','_____ (the/window) for _____ (cost-effective) _____ action _____ (not/close/yet), but _____ (it) _____ (narrow/has been) _____ significantly _____ in _____ recent _____ years as _____ (the) _____ cumulative _____ concentration of _____ (greenhouse) _____ gases _____ (reach) _____ levels that _____ (not/see/passive/previously).','The / window / has not yet closed / it / has been narrowing / significantly / recent / years / the / cumulative / concentration / greenhouse / gases / has reached / levels / had not previously been seen',NULL,'''Has not yet closed'' + ''has been narrowing/reached'' for climate window urgency.','hard'),

  -- BLOCK 73: PP com since e for
  (cid,73,231,'gap_fill','_____ (the/two/sides) _____ (not/hold) _____ direct _____ talks _____ since _____ (the) _____ breakdown of _____ (the) _____ negotiations _____ three _____ years _____ ago — _____ (the) _____ absence of _____ direct _____ (communication) _____ (complicate) _____ efforts to _____ (de-escalate) _____ tensions.','The / two sides / have not held / direct / talks / since / the / breakdown / of / the / negotiations / three / years / ago / the / absence / direct / communication / has complicated / efforts / de-escalate / tensions',NULL,'''Have not held'' + since + ''has complicated'' for prolonged diplomatic silence.','medium'),
  (cid,73,232,'gap_fill','_____ (the/institution) _____ (operate) under _____ (its) _____ current _____ mandate for _____ twenty _____ years — _____ (it) _____ (time/be) to _____ (review) whether _____ that _____ mandate _____ (still/reflect) _____ (the) _____ realities of _____ (the) _____ environment in _____ which _____ it _____ (now/operate).','The / institution / has been operating / under / its / current / mandate / for / twenty / years / it / is time / review / whether / that / mandate / still reflects / the / realities / the / environment / in / which / it / now operates',NULL,'''Has been operating'' + for + PS ''reflects/operates'' for mandate review rationale.','medium'),
  (cid,73,233,'gap_fill','Inequality _____ (widen) consistently _____ since _____ (the) _____ deregulation of _____ (the) _____ 1980s — a _____ trend that _____ (resist) _____ successive _____ policy _____ (intervention) and that _____ (show) _____ no sign of _____ (reverse) without _____ more _____ fundamental _____ structural _____ change.','has been widening / consistently / since / the / deregulation / the / 1980s / a / trend / has resisted / successive / policy / interventions / shows / no sign / reversing / without / more / fundamental / structural',NULL,'''Has been widening'' (for duration) + ''has resisted'' + PS ''shows'' for inequality trend.','hard'),
  (cid,73,234,'gap_fill','_____ (the/scientific) _____ (community) _____ (warn) about _____ (this) _____ risk for _____ decades — _____ (the) _____ evidence _____ (grow) more _____ compelling _____ with _____ each _____ passing _____ year, yet _____ policy _____ responses _____ (remain) _____ inadequate to _____ (the) _____ scale of _____ (the) _____ challenge.','The / scientific / community / has been warning / about / this / risk / for / decades / the / evidence / has grown / more / compelling / with / each / passing / year / yet / policy / responses / remain / inadequate / the / scale / the / challenge',NULL,'''Has been warning'' (for + decades) + ''has grown'' + PS ''remain'' for decades of unheeded warnings.','hard'),
  (cid,73,235,'multiple_choice','Which sentence MOST correctly uses ''since'' with present perfect?','The organization has maintained its independence since it was established in 1995.','["The organization maintained its independence since 1995.","The organization has maintained its independence since it was established in 1995.","The organization maintained its independence since being established.","The organization is maintaining its independence since 1995."]','PP ''has maintained'' + ''since'' + past simple ''was established'' = correct PP + since structure.','easy'),
  (cid,73,236,'gap_fill','_____ (the) _____ gap between _____ (the) _____ rich and _____ poor _____ (widen) _____ for _____ most of _____ (the) _____ past _____ half-century, _____ (reflect) _____ fundamental _____ changes in _____ how _____ (the) _____ economy _____ (operate) and _____ in _____ (how) _____ (the) _____ gains _____ from _____ growth _____ (distribute/passive).','The / gap / between / the / rich / poor / has been widening / for / most / the / past / half-century / reflecting / fundamental / changes / how / the / economy / operates / how / the / gains / growth / are distributed',NULL,'''Has been widening'' + for + ''reflecting'' (participial) + PS ''operates/distributed.''','hard'),
  (cid,73,237,'gap_fill','_____ (the/field) _____ (evolve) _____ rapidly _____ since _____ (the) _____ development of _____ new _____ (computational) _____ methods that _____ (allow) researchers to _____ (tackle) _____ problems that _____ (previously) _____ (beyond/be) _____ (the) _____ reach of _____ available _____ tools.','The / field / has evolved / rapidly / since / the / development / new / computational / methods / allow / researchers / tackle / problems / previously / were beyond / the / reach / available / tools',NULL,'''Has evolved'' + since + PS ''allow/are'' for computational method impact.','medium'),
  (cid,73,238,'gap_fill','_____ (the/court) _____ (issue) _____ only _____ a _____ handful of _____ rulings on _____ (this) _____ question _____ since _____ (the) _____ constitutional _____ (provision) in _____ question _____ (enact/passive) — _____ (the) _____ law _____ (remain) therefore _____ considerably _____ uncertain.','The / court / has issued / only / a / handful / rulings / this / question / since / the / constitutional / provision / in / question / was enacted / the / law / remains / therefore / considerably / uncertain',NULL,'''Has issued'' + since + PS ''was enacted/remains'' for legal uncertainty due to sparse precedent.','hard'),

  -- BLOCK 74: PP vs PS (contraste formal)
  (cid,74,239,'gap_fill','_____ (the) _____ government _____ (announce) the _____ policy _____ last _____ month, but _____ (it) _____ (not/explain) how _____ (it) _____ _____ (intend) to _____ (fund) it — _____ that _____ (remain) _____ the _____ central _____ unanswered _____ question.','The / government / announced / policy / last / month / it / has not explained / how / it / intends / fund / that / remains / the / central / unanswered / question',NULL,'PS ''announced'' (specific past time) + PP ''has not explained'' (still unanswered now).','medium'),
  (cid,74,240,'gap_fill','_____ (the/study) _____ (publish/passive) in _____ 2018 _____ (find) _____ a _____ significant _____ correlation, and _____ subsequent _____ work _____ (strengthen) _____ that _____ finding — _____ (the) _____ relationship _____ (now/consider/passive) _____ robust.','The / study / published / in / 2018 / found / a / significant / correlation / subsequent / work / has strengthened / that / finding / the / relationship / is now considered / robust',NULL,'PS ''published/found'' (specific year) + PP ''has strengthened'' (cumulative to now).','medium'),
  (cid,74,241,'gap_fill','When _____ (the/committee) _____ (meet) _____ last _____ year, _____ (it) _____ (review) _____ (the) _____ evidence _____ available _____ at _____ that _____ time — _____ since _____ then, _____ substantial _____ new _____ data _____ (emerge) that _____ (not/available/be) for _____ (that) _____ review.','the / committee / met / last / year / it / reviewed / the / evidence / available / at / that / time / since / then / substantial / new / data / has emerged / was not available / that / review',NULL,'PS ''met/reviewed'' (specific past event) + PP ''has emerged'' (since then to now).','hard'),
  (cid,74,242,'multiple_choice','Which contrast CORRECTLY distinguishes present perfect from past simple?','The government introduced the policy in 2020, but experts have questioned its effectiveness ever since.','["The government has introduced the policy in 2020, but experts questioned its effectiveness.","The government introduced the policy in 2020, but experts have questioned its effectiveness ever since.","The government has introduced the policy in 2020, but experts have questioned its effectiveness in 2020.","The government introduced the policy in 2020, but experts questioned its effectiveness in 2022."]','PS ''introduced'' (specific year 2020) + PP ''have questioned'' (from 2020 until now = ''ever since'').','easy'),
  (cid,74,243,'gap_fill','_____ (the/parliament) _____ (debate) _____ (the) _____ measure _____ for _____ three _____ months in _____ 2021 _____ before _____ (pass) it — _____ (the/critics) _____ who _____ (oppose) it _____ then _____ (not/change) _____ (their) _____ view _____ since.','The / parliament / debated / the / measure / for / three / months / in / 2021 / before / passing / the critics / who / opposed / it / then / have not changed / their / view / since',NULL,'PS ''debated/opposed'' (2021) + PP ''have not changed'' (from then to now).','medium'),
  (cid,74,244,'gap_fill','_____ (the/framework) _____ (establish/passive) in _____ 1994 and _____ (serve) as _____ (the) _____ basis for _____ (the) _____ subsequent _____ development of _____ (the) _____ field — _____ (it) _____ (be) _____ (modify) _____ several _____ times _____ since, but _____ (its) _____ core _____________________________________________________ (endure).','The / framework / was established / in / 1994 / served / as / the / basis / the / subsequent / development / the / field / it / has been / modified / several / times / since / its / core / principles / have endured',NULL,'PS ''was established/served'' (1994) + PP ''has been modified/have endured'' (since 1994).','hard'),
  (cid,74,245,'gap_fill','When _____ (the/analyst) _____ (write) _____ (this) _____ in _____ 2019, _____ (the) _____ situation _____ (appear) _____ more _____ manageable _____ than _____ (it) _____ (turn out) to _____ (be) — _____ events _____ since _____ (demonstrate) that _____ (the) _____ underlying _____ vulnerabilities _____ (more severe/be) than _____ (recognize/passive) at _____ (the) _____ time.','the / analyst / wrote / this / in / 2019 / the / situation / appeared / more / manageable / than / it / turned out / to / be / events / since / have demonstrated / the / underlying / vulnerabilities / were more severe / than / recognised / the / time',NULL,'PS ''wrote/appeared/turned out'' (2019) + PP ''have demonstrated'' (events since 2019).','hard'),
  (cid,74,246,'gap_fill','_____ (the/founders) _____ (design) _____ (the) _____ institution _____ to _____ (serve) _____ needs of _____ their _____ era — _____ needs that _____ (change) _____ considerably _____ since _____ (the) _____ original _____ mandate _____ (draft/passive).','The / founders / designed / the / institution / serve / the / needs / their / era / needs / have changed / considerably / since / the / original / mandate / was drafted',NULL,'PS ''designed/was drafted'' + PP ''have changed'' for institutional adaptation argument.','medium'),

  -- BLOCK 75: PP passivo
  (cid,75,247,'gap_fill','_____ (the/evidence) _____ (extensively/review/passive) by _____ (an) _____ independent _____ panel — _____ (the) _____ methodology _____ (scrutinize/passive) carefully, _____ (the) _____ (assumption) _____ (test/passive) against _____ alternatives, and _____ (the) _____ conclusions _____ (challenge/passive) from _____ multiple _____ perspectives.','The / evidence / has been extensively reviewed / an / independent / panel / the / methodology / has been carefully scrutinised / the / assumptions / have been tested / against / alternatives / the / conclusions / have been challenged / multiple / perspectives',NULL,'PP passive ''has been reviewed/scrutinised/tested/challenged'' for thorough independent review.','medium'),
  (cid,75,248,'gap_fill','_____ (the/regulatory) _____ threshold _____ (not/adjust/passive) since _____ (the) _____ regulation _____ (first/introduce/passive) — _____ (a) _____ gap that _____ (flag/passive) _____ repeatedly by _____ (those) _____ responsible for _____ (implementation) but that _____ (address/passive/not) by _____ (the) _____ responsible _____ ministry.','The / regulatory / threshold / has not been adjusted / since / the / regulation / was first introduced / a / gap / that / has been flagged / repeatedly / those / responsible / implementation / has not been addressed / the / responsible / ministry',NULL,'PP passive ''has not been adjusted/flagged/not been addressed'' for regulatory inaction.','hard'),
  (cid,75,249,'gap_fill','_____ (the/measure) _____ (adopt/passive) without _____ adequate _____ consultation — _____ (the) _____ stakeholder groups _____ most _____ (affect/passive) by _____ it _____ (not/consult/passive) and _____ (their) _____ concerns _____ (not/incorporate/passive) into _____ (the) _____ design.','The / measure / has been adopted / without / adequate / consultation / the / stakeholder / groups / most / affected / it / have not been consulted / their / concerns / have not been incorporated / into / the / design',NULL,'PP passive ''has been adopted/have not been consulted/not been incorporated'' for process failure.','hard'),
  (cid,75,250,'gap_fill','_____ (the/mechanism) _____ (design/passive) carefully to _____ (avoid) _____ (the) _____ conflicts of _____ interest that _____ (undermine) _____ previous _____ arrangements — _____ (the) _____ (safeguard) _____ (put/passive) _____ in _____ place and _____ (test/passive) _____ through _____ (the) _____ first _____ operational _____ cycle.','The / mechanism / has been carefully designed / avoid / the / conflicts / interest / undermined / previous / arrangements / the / safeguards / have been put / in / place / tested / through / the / first / operational / cycle',NULL,'PP passive ''has been designed/put/tested'' + PS ''undermined'' for improved mechanism design.','hard'),
  (cid,75,251,'multiple_choice','Which sentence MOST correctly uses the present perfect passive?','The funding has been allocated but has not yet been disbursed to implementing partners.','["The funding was allocated but was not yet disbursed.","The funding has been allocated but has not yet been disbursed to implementing partners.","The funding is allocated but has not been disbursed.","The funding was allocated but has not been disbursed yet."]','PP passive ''has been allocated/not yet been disbursed'' = both in same time frame with current relevance.','easy'),
  (cid,75,252,'gap_fill','_____ (the/issue) _____ (raise/passive) _____ at _____ every _____ meeting _____ for _____ _____ (the) _____ past _____ two _____ years, but _____ (it) _____ (not/resolve/passive) — _____ (the) _____ technical _____ (complexity) of _____ (the) _____ problem _____ (always/cite/passive) as _____ (a) _____ reason _____ for _____ (further) _____ delay.','The / issue / has been raised / at / every / meeting / for / the / past / two / years / it / has not been resolved / the / technical / complexity / the / problem / has always been cited / as / a / reason / for / further / delay',NULL,'PP passive ''has been raised/not been resolved/been cited'' for chronic unresolved issue.','hard'),
  (cid,75,253,'gap_fill','_____ (the/community) _____ (affect/passive) _____ disproportionately by _____ (the) _____ policy _____ changes — _____ (the) _____ services on which _____ (it) _____ (rely) _____ (reduce/passive) significantly, _____ (the) _____ infrastructure _____ (not/maintain/passive) adequately, and _____ (the) _____ concerns _____ of _____ (its) _____ residents _____ (not/hear/passive).','The / community / has been affected / disproportionately / the / policy / changes / the / services / it / relies / have been reduced / significantly / the / infrastructure / has not been maintained / adequately / the / concerns / its / residents / have not been heard',NULL,'PP passive chain ''has been affected/reduced/not maintained/not heard'' for community impact.','hard'),
  (cid,75,254,'gap_fill','_____ (the/approach) _____ (validate/passive) across _____ multiple _____ contexts and _____ (recommend/passive) by _____ (a) _____ number of _____ authoritative _____ bodies — _____ (it) _____ (time/be) to _____ (scale) it _____ rather than _____ (continue) to _____ (pilot) it in _____ (an) _____ ever-expanding _____ series of _____ limited _____ trials.','The / approach / has been validated / across / multiple / contexts / recommended / by / a / number / authoritative / bodies / it / is time / scale / rather / continuing / pilot / it / an / ever-expanding / series / limited / trials',NULL,'PP passive ''has been validated/recommended'' + ''is time to scale'' for evidence-based scale-up argument.','hard'),

  -- BLOCK 76: TOEFL Reading com PP
  (cid,76,255,'multiple_choice','[TOEFL Reading] ''Scientists have recently discovered a mechanism that may explain the observed anomaly.'' What does ''have recently discovered'' indicate?','A recent finding whose implications are still being explored.','["A discovery made long ago","A planned future discovery","A recent finding whose implications are still being explored.","A discovery that was immediately confirmed"]','''Have recently discovered'' = PP for recent past with ongoing current relevance.','easy'),
  (cid,76,256,'gap_fill','[TOEFL Reading] ''_____ (the/evidence) _____ (accumulate) to _____ (the) _____ point where _____ denial _____ (no longer/tenable/be) — _____ (the/question) now _____ (be) not whether _____ (the) _____ phenomenon _____ (occur) but how _____ rapidly _____ and _____ (what) _____ (the) _____ consequences _____ will be.'' Best forms?','The / evidence / has accumulated / to / the / point / where / denial / is no longer tenable / the question / now / is / not / whether / the / phenomenon / is occurring / how / rapidly / what / the / consequences',NULL,'PP ''has accumulated'' (current critical mass) + PS/PC ''is, is occurring'' for present reality.','medium'),
  (cid,76,257,'gap_fill','[TOEFL Reading] ''The approach _____ (demonstrate) _____ its _____ (value) _____ across _____ multiple _____ (context) — in each case, _____ (the) _____ (implementation) _____ (produce) _____ (outcome) _____ that _____ (outperform) _____ (those/achieve/passive) through _____ conventional _____ methods.'' Best forms?','has demonstrated / its / value / across / multiple / contexts / the / implementation / produced / outcomes / outperformed / those / achieved / conventional / methods',NULL,'PP ''has demonstrated'' (cumulative) + PS ''produced/outperformed'' (each case in past).','medium'),
  (cid,76,258,'gap_fill','[TOEFL Reading] ''Researchers _____ (long/argue) that _____ (the) _____ conventional _____ model _____ (not/capture) _____ (the) _____ full _____ complexity of _____ (the) _____ phenomenon — and _____ new _____ (evidence) _____ (emerge) that _____ (support) _____ this _____ critique.'' Best forms?','have long argued / the / conventional / model / does not capture / the / full / complexity / the / phenomenon / new / evidence / has emerged / that / supports / this / critique',NULL,'PP ''have long argued/has emerged'' + PS ''does not capture/supports.''','medium'),
  (cid,76,259,'gap_fill','[TOEFL Reading] ''The policy _____ (achieve) _____ its _____ (primary) _____ objective, but _____ (it) _____ (also/generate) _____ (unintended) _____ (consequence) that _____ (now/require) _____ (address).'' Best forms?','has achieved / its / primary / objective / it / has also generated / unintended / consequences / now require / addressing',NULL,'PP ''has achieved/generated'' for policy evaluation with current consequences.','medium'),
  (cid,76,260,'multiple_choice','[TOEFL Reading] ''The debate has shifted from whether the intervention works to how it can be scaled.'' What does ''has shifted'' communicate?','The debate has evolved to a new stage, with current implications for policy.','["The debate shifted in the past and is over now","The debate has evolved to a new stage, with current implications for policy.","The debate was about scaling all along","The debate will shift in the future"]','PP ''has shifted'' = change with current relevance; the new stage IS the current state of the debate.','easy'),
  (cid,76,261,'gap_fill','[TOEFL Reading] ''Although the institution _____ (face) _____ criticism in _____ its _____ early _____ years, _____ (it) _____ (gradually/establish) _____ itself as _____ (an) _____ authoritative _____ body whose _____ (finding) _____ (command) _____ broad _____ respect.'' Best forms?','faced / criticism / its / early / years / it / has gradually established / itself / an / authoritative / findings / command / broad / respect',NULL,'PS ''faced'' (early years, completed period) + PP ''has established'' (gradual, current state).','medium'),
  (cid,76,262,'gap_fill','[TOEFL Reading] ''The technology _____ (mature) _____ significantly _____ since _____ (its) _____ initial _____ development, _____ and _____ (the) _____ costs _____ (fall) _____ to _____ (the) _____ point _____ where _____ _____ (widespread) _____ deployment _____ (now/financially/viable/be).'' Best forms?','has matured / significantly / since / its / initial / development / the / costs / have fallen / to / the / point / where / widespread / deployment / is now financially viable',NULL,'PP ''has matured/have fallen'' + since + PS ''is now'' for technology readiness.','medium'),

  -- BLOCK 77: TOEFL Speaking com PP
  (cid,77,263,'production','[TOEFL Speaking — 45s] A reading describes how the understanding of a scientific phenomenon has changed. Summarize using present perfect.','',NULL,'The reading describes how the scientific understanding of the phenomenon has changed significantly over the past several decades. Early researchers believed the effect was primarily driven by a single mechanism, but subsequent work has revealed that multiple interacting processes are involved, each contributing differently under different conditions. The reading notes that this more complex understanding has emerged gradually as researchers have developed new tools that allow them to observe the phenomenon at finer levels of resolution. Several assumptions that the field had long taken for granted have been challenged by this new evidence, and the theoretical framework has had to be substantially revised to accommodate what has been learned. The reading concludes that while the field has made significant progress, important questions remain unresolved, and the new complexity of the picture that has emerged means that simple predictions about the phenomenon''s behavior are no longer possible.','hard'),
  (cid,77,264,'production','[TOEFL Speaking — 45s] A professor discusses what changes have occurred in a field of study over the past decade. Use present perfect throughout.','',NULL,'The professor describes several important changes that have occurred in the field over the past decade. First, the methods used to collect and analyze data have improved substantially — researchers have gained access to significantly larger and more diverse datasets, and the statistical tools they use to analyze those datasets have become considerably more sophisticated. Second, the theoretical frameworks that guide research have become more integrated — scholars who previously worked in relative isolation have increasingly recognized the connections between their work and have begun to build on each other''s findings more systematically. Third, the field has become more policy-relevant — researchers have moved closer to practitioners and policymakers, and the questions the field has prioritized have reflected the concerns of those who actually need to make decisions based on the research. The professor concludes that the field has not solved its core problems, but it has developed a much clearer sense of what those problems are and a more realistic assessment of what kinds of answers are achievable — which itself represents significant progress.','hard'),
  (cid,77,265,'production','[TOEFL Speaking — 60s] Discuss what evidence has accumulated about the effects of a policy, using present perfect throughout.','',NULL,'The evidence that has accumulated about the effects of this policy over the years of its implementation paints a complex picture that resists simple characterization as either a success or a failure. On the positive side, the evidence has consistently shown that the groups the policy targeted have experienced improvements in the outcomes the policy was designed to address. Multiple independent evaluations have confirmed that these improvements are attributable to the policy rather than to other factors, and the effect sizes have proved larger than critics initially predicted. The policy has also generated positive spillovers that were not anticipated at the outset — it has produced improvements in outcomes beyond those it was directly targeting, because the mechanisms through which it operates have turned out to have broader effects than the designers recognized. On the negative side, the evidence has also revealed implementation problems that have limited the policy''s reach and effectiveness in certain contexts. Evaluations have identified significant variation in outcomes across different sites, and researchers have linked this variation to differences in the quality of implementation rather than to differences in the populations served. The evidence has also revealed unintended costs — groups not directly targeted by the policy have in some contexts experienced negative effects that the designers did not anticipate and that have not been adequately addressed. Overall, the accumulated evidence has made clear that the policy works, but also that it can work much better if the implementation failures that have been documented are corrected.','hard'),
  (cid,77,266,'gap_fill','[TOEFL Speaking] The evidence _____ (suggest) that _____ the _____ (approach) _____ (demonstrate) _____ (its) _____ (merit) _____ in _____ controlled _____ settings but _____ (not/yet/prove) _____ equally _____ effective at _____ (the) _____ scale and _____ in _____ (the) _____ contexts where _____ (it) _____ (most/need/passive).','has suggested / the / approach / has demonstrated / its / merits / in / controlled / settings / has not yet proved / equally / effective / the / scale / the / contexts / it / is most needed',NULL,'PP ''has suggested/demonstrated/not yet proved'' for evidence-based TOEFL analysis.','hard'),

  -- BLOCK 78: TOEFL Writing com PP
  (cid,78,267,'production','[TOEFL Writing — 200 words] Write a body paragraph summarizing what research has demonstrated about a social intervention.','',NULL,'The research literature on early childhood education has now accumulated sufficient evidence to support several robust conclusions about what kinds of programs work and for whom. Studies conducted over decades have consistently demonstrated that high-quality early childhood programs produce lasting improvements in educational outcomes, with participants achieving higher levels of attainment than comparable children who did not participate. Longitudinal research has tracked these participants into adulthood and has found that the benefits extend well beyond educational attainment — participants have demonstrated higher rates of employment, higher earnings, lower involvement in the criminal justice system, and better health outcomes than the control groups. Researchers have also examined the mechanisms through which these benefits operate and have found that the programs work primarily by supporting the development of the non-cognitive skills — self-regulation, persistence, the ability to work with others — that predict success in school and in later life. The evidence has been sufficiently consistent and sufficiently strong that the question of whether high-quality early childhood education works is no longer genuinely contested in the research literature. What has remained contested — and what the evidence has not yet resolved — is the question of which specific program features are most essential to producing the documented outcomes, and how much quality can be compromised before the benefits diminish significantly.','hard'),
  (cid,78,268,'production','[TOEFL Writing — 200 words] Write a paragraph using present perfect to analyze how climate science has evolved.','',NULL,'Climate science has evolved dramatically over the past half century, transforming from a relatively marginal field into one of the most intensively studied and policy-relevant domains of scientific inquiry. Researchers have developed increasingly sophisticated models of the climate system that have allowed them to understand not just the broad direction of change but the regional patterns and sector-specific impacts that matter most for adaptation planning. Observational data has accumulated from satellite systems, ocean buoys, ice cores, and weather stations that have collectively provided an unprecedented understanding of how the climate has behaved in the past and how it is changing in the present. Scientists have identified feedback mechanisms that had not been recognized in earlier models and have revised upward their estimates of climate sensitivity as a result. The scientific consensus has hardened around the conclusion that human activities are the dominant driver of the warming that has been observed since the pre-industrial period — a conclusion that was contested two decades ago but has since been confirmed by multiple independent lines of evidence. What has changed most fundamentally is not just the knowledge base but the confidence with which that knowledge can be translated into projections — the uncertainty ranges have narrowed, the regional differentiation has improved, and the connection between emissions scenarios and physical outcomes has been established with increasing precision.','hard'),
  (cid,78,269,'gap_fill','[TOEFL Writing] _____ (the/evidence) _____ (make/passive) _____ clear beyond _____ reasonable _____ (doubt) that _____ (the) _____ phenomenon _____ (real/is) and _____ (consequential) — _____ (the/question) that _____ (remain) is _____ what _____ to _____ do _____ about _____ it, _____ not _____ whether _____ to.','The / evidence / has made / clear / beyond / reasonable / doubt / the / phenomenon / is real / consequential / the question / remains / what / to / do / about / it / not / whether / to',NULL,'PP ''has made'' + PS ''remains/is'' for evidence-based conclusion shifting to action question.','medium'),
  (cid,78,270,'gap_fill','[TOEFL Writing] The field _____ (come) _____ a _____ long _____ way _____ since _____ (the) _____ early _____ (stage) of _____ (its) _____ development — _____ (the) _____ methods _____ (improve), _____ (the) _____ evidence _____ base _____ (grow), and _____ (the) _____ understanding _____ (deepen) in _____ ways that _____ (allow) _____ more _____ confident _____ (application) to _____ real-world _____ problems.','has come / a / long / way / since / the / early / stages / its / development / the / methods / have improved / the / evidence / base / has grown / the / understanding / has deepened / in / ways / allow / more / confident / application / real-world / problems',NULL,'PP ''has come/improved/grown/deepened'' for cumulative field progress since early stages.','medium'),
  (cid,78,271,'gap_fill','[TOEFL Writing] _____ (the/argument) _____ (not/engage/passive) _____ seriously _____ by _____ (mainstream) _____ scholarship _____ until _____ recently — _____ (it) _____ (dismiss/passive) _____ as _____ outside _____ (the) _____ mainstream, _____ but _____ new _____ evidence _____ (lend) _____ it _____ greater _____ credibility.','The / argument / has not been engaged / seriously / by / mainstream / scholarship / until / recently / it / has been dismissed / as / outside / the / mainstream / but / new / evidence / has lent / it / greater / credibility',NULL,'PP passive ''has not been engaged/been dismissed'' + PP ''has lent'' for emerging scholarly rehabilitation.','hard'),
  (cid,78,272,'gap_fill','[TOEFL Writing] In _____ sum, _____ (the) _____ evidence _____ (point) _____ consistently _____ in _____ one _____ direction — _____ (the) _____ research _____ community _____ (reach) _____ consensus, _____ (the) _____ policy _____ implications _____ (draw/passive), and _____ (the) _____ time for _____ (act) _____ (pass).','In / sum / the / evidence / has pointed / consistently / one / direction / the / research / community / has reached / consensus / the / policy / implications / have been drawn / the / time / acting / has passed',NULL,'PP ''has pointed/reached/been drawn/passed'' for conclusive evidence-to-action argument.','hard'),

  -- BLOCK 79: Gap fill avançado com PP
  (cid,79,273,'gap_fill','_____ (never) _____ (there/be) _____ such _____ (a) _____ moment _____ in _____ (the) _____ history of _____ (the) _____ field when _____ so _____ much _____ (know/passive) and _____ yet _____ so _____ (little) _____ (do/passive) with _____ that _____ knowledge — _____ (the) _____ gap between _____ evidence and _____ action _____ (never/wider/be).','Never / has there been / such / a / moment / in / the / history / the / field / so / much / has been known / so / little / has been done / that / knowledge / the / gap / between / evidence / action / has never been wider',NULL,'Inverted PP ''never has there been'' + PP passives + superlative PP ''has never been wider.''','hard'),
  (cid,79,274,'gap_fill','_____ (it) _____ (rare/be) for _____ (a) _____ policy _____ to _____ (achieve) _____ all _____ of _____ (its) _____ stated _____ objectives — _____ (this) _____ one _____ (be) no _____ exception, _____ (manage) to _____ (deliver) on _____ some _____ while _____ (fall short) on _____ others in _____ ways that _____ (now/clearly/document/passive).','It / has rarely been / for / a / policy / achieve / all / its / stated / objectives / this / one / is / no / exception / managing / deliver / on / some / while / falling short / on / others / that / are now clearly documented',NULL,'PP ''has rarely been'' + PS ''is'' + PP passive ''are documented'' for policy evaluation.','hard'),
  (cid,79,275,'gap_fill','What _____ (begin) as _____ (a) _____ local _____ experiment _____ (grow) into _____ (a) _____ global _____ movement — _____ ideas that _____ (generate) in _____ one _____ context _____ (travel) across _____ borders and _____ (inspire) _____ (adaptation) in _____ settings _____ very _____ different from _____ (the) _____ original.','began / as / a / local / experiment / has grown / into / a / global / movement / ideas / were generated / in / one / context / have travelled / across / borders / inspired / adaptations / in / settings / very / different / the / original',NULL,'PS ''began/generated'' + PP ''has grown/have travelled/inspired'' for local-to-global diffusion.','medium'),
  (cid,79,276,'gap_fill','Rarely _____ (an/approach) _____ (demonstrate) _____ (its) _____ effectiveness as _____ conclusively as _____ (this) _____ one _____ (do) — (the) _____ evidence _____ (cumulate) from _____ multiple _____ independent _____ studies _____ conducted across _____ diverse _____ contexts, and _____ (the) _____ consistency of _____ (the) _____ findings _____ (impressive/be).','Rarely / has an approach / demonstrated / its / effectiveness / as / conclusively / as / this / one / has / the / evidence / has cumulatively emerged / from / multiple / independent / studies / diverse / contexts / the / consistency / the / findings / is impressive',NULL,'Inverted PP ''Rarely has an approach demonstrated'' for emphatic evaluation.','hard'),
  (cid,79,277,'gap_fill','_____ (the/theory) _____ (stand) _____ the _____ test of _____ time — _____ every _____ serious _____ attempt to _____ (disconfirm) it _____ (fail), and _____ (the) _____ evidence _____ in _____ its _____ (favour) _____ (only/grow) _____ (stronger) as _____ more _____ data _____ (accumulate).','The / theory / has stood / the / test / time / every / serious / attempt / disconfirm / it / has failed / the / evidence / in / its / favour / has only grown / stronger / as / more / data / accumulates',NULL,'PP ''has stood/failed/grown'' for theory vindication by accumulated evidence.','medium'),
  (cid,79,278,'gap_fill','_____ (the/situation) _____ (change) _____ fundamentally _____ since _____ (the) _____ initial _____ assessment — _____ (the) _____ conditions that _____ (obtain) then _____ (no longer/obtain) and _____ (the) _____ analysis _____ (conduct/passive) at _____ that _____ time _____ (no longer/apply).','The / situation / has changed / fundamentally / since / the / initial / assessment / the / conditions / that / obtained / then / no longer obtain / the / analysis / conducted / at / that / time / no longer applies',NULL,'PP ''has changed'' + PS ''obtained/no longer obtain/applies'' for changed circumstances.','hard'),
  (cid,79,279,'gap_fill','What _____ (most/strike) _____ observers about _____ (the) _____ trajectory of _____ (the) _____ field _____ (be) not _____ how _____ much _____ (it) _____ (change) but _____ how _____ consistent _____ (the) _____ core _____ (finding) _____ (remain) _____ across _____ methodological _____ and _____ contextual _____ variation.','has most struck / observers / the / trajectory / the / field / is / not / how / much / it / has changed / but / how / consistent / the / core / findings / have remained / across / methodological / contextual',NULL,'PP ''has struck/changed/remained'' for consistent core findings despite evolution.','hard'),
  (cid,79,280,'gap_fill','_____ (the/discipline) _____ (struggle) for _____ decades with _____ (the) _____ problem of _____ (how) to _____ (integrate) _____ qualitative and _____ quantitative _____ approaches — _____ (recent) _____ methodological _____ (development) _____ (begin) to _____ (bridge) _____ (that) _____ divide, but _____ much _____ (remain) to _____ (do).','The / discipline / has struggled / for / decades / with / the / problem / how / integrate / qualitative / quantitative / approaches / recent / methodological / developments / have begun / bridge / that / divide / but / much / remains / to / do',NULL,'PP ''has struggled/begun'' + ''remains'' for ongoing methodological integration challenge.','medium'),

  -- BLOCK 80: Exercícios finais de produção
  (cid,80,281,'production','[TOEFL Writing — 200 words] Write a conclusion synthesizing what the research has shown about a complex social problem.','',NULL,'The research reviewed in this essay has collectively produced a picture of the problem that is more complex and more consequential than policymakers have generally recognized. Studies have consistently found that the problem is driven by multiple reinforcing factors rather than by a single cause, and this finding has important implications for intervention design — no single-factor intervention has proved adequate, and the evidence has instead supported the case for integrated approaches that address multiple determinants simultaneously. Researchers have also found that the problem is more tractable than its persistence might suggest: where comprehensive interventions have been implemented with adequate resources and sustained commitment, they have produced significant improvements, and these improvements have been maintained over time rather than fading as initial enthusiasm dissipated. What the research has not yet resolved is the question of how these lessons can be translated into routine policy and practice at scale — the gap between what the evidence has shown works and what governments actually do has proved stubborn. The research has generated the knowledge needed to address the problem; what has been lacking is the political will and institutional capacity to act on that knowledge consistently and at the scale the problem requires. Closing this gap between evidence and action is the most important challenge the field has identified and has not yet solved.','hard'),
  (cid,80,282,'production','[TOEFL Speaking — 60s] The reading and lecture both discuss what has changed in an institution. Summarize each and their relationship.','',NULL,'Both the reading and the lecture discuss changes that have occurred in the institution, but they reach different assessments of what those changes mean. The reading notes that the institution has undergone significant formal restructuring over the past decade: it has revised its mandate, has reformed its governance structures, has introduced new accountability mechanisms, and has expanded its engagement with civil society and the private sector. The reading presents these changes as evidence of genuine institutional evolution and argues that the institution has demonstrated an ability to adapt that many predicted it would lack. The professor agrees with the reading''s description of what has changed but challenges its interpretation of what those changes mean. She argues that while the institution has reformed its procedures and structures, it has not changed the fundamental culture and incentive structures that have historically limited its effectiveness. The key personnel who have risen to leadership positions have continued to reflect the same priorities and perspectives that guided the institution before the reforms, and the new accountability mechanisms have not yet been tested in situations where applying them would impose real costs on powerful members. The professor concludes that the institution has changed more in form than in substance, and that the genuinely important test of whether it has reformed — whether it will act differently in situations of genuine difficulty — has not yet come.','hard'),
  (cid,80,283,'gap_fill','[TOEFL Writing] Much _____ (achieve/passive) — _____ (and) _____ (the) _____ progress _____ (make/passive) _____ (deserve) _____ recognition — but _____ (much) _____ (also/remain) to _____ (do) _____ before _____ (the) _____ goals _____ (set) _____ out at _____ (the) _____ outset _____ (reach/passive).','has been achieved / and / the / progress / made / deserves / recognition / much / also remains / do / the / goals / set / the / outset / are reached',NULL,'PP passive ''has been achieved/made'' + PS ''remains/are reached'' for partial progress assessment.','medium'),
  (cid,80,284,'gap_fill','_____ (this) _____ analysis _____ (demonstrate) _____ that _____ (the) _____ relationship _____ between _____ (the) _____ two _____ variables _____ (more complex/prove) than _____ (the) _____ literature _____ (generally/assume) — _____ (the) _____ simple _____ model _____ (no longer/adequate/be) in _____ light of _____ what _____ (learn/passive).','This / analysis / has demonstrated / that / the / relationship / between / the / two / variables / has proved more complex / than / the / literature / has generally assumed / the / simple / model / is no longer adequate / light / what / has been learned',NULL,'PP ''has demonstrated/proved/assumed/been learned'' for analytical finding with current implications.','hard'),
  (cid,80,285,'gap_fill','Few _____ issues _____ in _____ (the) _____ contemporary _____ debate _____ (generate) _____ more _____ heat _____ and _____ less _____ light _____ than _____ this _____ one — _____ (the) _____ quality of _____ (the) _____ discourse _____ (not/improve/passive) as _____ (the) _____ stakes _____ (rise) and _____ (the) _____ urgency _____ (grow).','Few / issues / in / the / contemporary / debate / have generated / more / heat / less / light / than / the / quality / the / discourse / has not improved / as / the / stakes / rise / the / urgency / grows',NULL,'PP ''have generated/has not improved'' + PS ''rise/grows'' for quality-of-debate critique.','medium'),
  (cid,80,286,'gap_fill','It _____ (be) _____ a _____ remarkable _____ characteristic _____ of _____ (this) _____ question that _____ it _____ (resist) _____ easy _____ resolution despite _____ decades of _____ intensive _____ study — _____ (the) _____ evidence _____ (accumulate) _____ and _____ (the) _____ tools _____ (improve), _____ yet _____ (the) _____ core _____ (dispute) _____ (remain) _____ (stubbornly/live).','has been / a / remarkable / characteristic / this / question / that / has resisted / easy / resolution / despite / decades / intensive / study / the / evidence / has accumulated / the / tools / have improved / yet / the / core / disputes / remain / stubbornly alive',NULL,'PP ''has resisted/accumulated/improved'' + PS ''remain'' for persistent scholarly controversy.','hard'),
  (cid,80,287,'gap_fill','_____ (the) _____ generation that _____ (build) _____ these _____ institutions _____ (now/pass) — _____ (the) _____ question is _____ whether _____ (those) who _____ (come) _____ after _____ (inherit) not _____ only _____ (their) _____ achievements but _____ also _____ (their) _____ understanding of _____ why _____ those _____ achievements _____ (matter).','The / generation / built / these / institutions / has now passed / the / question / is / whether / those / who / come / after / will inherit / not / only / their / achievements / also / their / understanding / why / those / achievements / matter',NULL,'PS ''built'' + PP ''has now passed'' + future ''will inherit'' for generational legacy question.','hard'),
  (cid,80,288,'gap_fill','In _____ many _____ ways, _____ (the) _____ hardest _____ part of _____ (the) _____ task _____ (only/begin) — _____ (the) _____ easy _____ questions _____ (resolve/passive), _____ (the) _____ clear _____ (failure) _____ (identify/passive), and _____ (the) _____ obvious _____ improvements _____ (implement/passive). _____ What _____ (remain) _____ (be) _____ (the) _____ questions that _____ (resist) _____ easy _____ answers.','In / many / ways / the / hardest / part / the / task / has only begun / the / easy / questions / have been resolved / the / clear / failures / have been identified / the / obvious / improvements / have been implemented / What / remains / is / the / questions / resist / easy / answers',NULL,'PP ''has only begun/have been resolved/identified/implemented'' + PS ''remains/resist'' for hard work ahead.','hard'),
  (cid,80,289,'production','[TOEFL Writing — 200 words] Final capstone paragraph using present perfect throughout to assess the state of knowledge in a field.','',NULL,'The field has reached a mature stage in its development, characterized by a clearer sense of what it knows with confidence, what it knows provisionally, and what it does not yet know. Researchers have established several findings with sufficient consistency that they can be treated as reliable foundations for further inquiry and for evidence-based policy. They have also identified the key areas of remaining uncertainty and have made significant progress in characterizing the nature and sources of that uncertainty, which is itself valuable knowledge. The theoretical frameworks that guide the field have been substantially refined through iterative testing against empirical evidence, and those that have proved inadequate have been revised or replaced. The methods available to researchers have improved dramatically, enabling questions to be addressed that were previously inaccessible, and the data infrastructure has been built that supports systematic investigation across diverse contexts. At the same time, the field has not resolved all the questions it has set for itself, and honest self-assessment requires acknowledging this. Several important debates have not yet been resolved, and the evidence that has accumulated does not yet support confident conclusions in all areas. The field has earned the right to be taken seriously as a basis for policy by virtue of what it has demonstrated; it has not yet earned the right to claim that the work is done.','hard'),
  (cid,80,290,'gap_fill','The most important thing _____ (the/field) _____ (learn) is not _____ any _____ specific _____ (finding) but _____ the _____ limits of _____ what _____ it _____ (can) _____ (confidently) _____ (claim) — _____ intellectual _____ humility that _____ (earn/passive) through _____ (the) _____ process of _____ testing _____ claims _____ against _____ evidence and _____ (find) some _____ of _____ them _____ (wanting).','the field / has learned / any / specific / finding / the / limits / what / it / can / confidently / claim / intellectual / humility / has been earned / through / the / process / testing / claims / against / evidence / finding / some / them / wanting',NULL,'PP ''has learned/been earned'' for epistemic maturity through empirical discipline.','hard'),
  (cid,80,291,'production','[TOEFL Speaking — 45s] Summarize what recent evidence has revealed about a previously held assumption.','',NULL,'Recent evidence has revealed that a key assumption that had long underpinned the field''s approach to this problem is significantly less reliable than researchers had believed. The assumption was that the relationship between the independent and dependent variable was linear — that more of the cause would produce proportionally more of the effect across the full range of conditions. This assumption has now been challenged by a series of studies that have found strong evidence of non-linearity: at low levels of exposure the effect appears to be small or absent, while at higher levels it becomes much stronger, and at very high levels there appears to be a threshold beyond which the relationship changes direction. This finding has important implications for how the research has been interpreted and for the policies that have been based on that research. Several interventions that researchers have recommended based on the earlier linear model may have been applied at doses that placed recipients in the flat or negative portion of the response curve, which would explain the weaker-than-expected results that evaluation research has consistently found. The field has acknowledged these findings and has begun to revise its models, but the policy implications have not yet been fully incorporated into practice.','hard'),
  (cid,80,292,'gap_fill','The trajectory of _____ (the/field) _____ (demonstrate) _____ something _____ (important): _____ genuine _____ progress _____ (possible/is) in _____ understanding _____ complex _____ social _____ phenomena, but _____ it _____ (require) _____ patience, _____ methodological _____ discipline, and _____ willingness to _____ (revise) _____ (one''s) _____ views when _____ (the) _____ evidence _____ (demand) it.','the field / has demonstrated / something / important / genuine / progress / is possible / in / understanding / complex / social / phenomena / but / it / requires / patience / methodological / discipline / a / willingness / revise / one''s / views / when / the / evidence / demands / it',NULL,'PP ''has demonstrated'' + PS ''is possible/requires/demands'' for field achievement lesson.','medium'),
  (cid,80,293,'gap_fill','What _____ (the/analysis) _____ (confirm) is that _____ (the/problem) _____ (not/simply/disappear) with _____ time — active _____ intervention _____ (necessary/be) and _____ (the/evidence) _____ to _____ (guide) _____ that _____ intervention _____ (now/available) _____ in _____ (an) _____ abundance that _____ (not/imagine/passive) _____ two _____ decades _____ ago.','the analysis / has confirmed / the problem / does not simply disappear / with / time / active / intervention / is necessary / the evidence / to / guide / that / intervention / is now available / in / an / abundance / could not have been imagined / two / decades / ago',NULL,'PP ''has confirmed/been imagined'' + PS ''does not/is necessary/is now available'' for evidence availability conclusion.','hard'),
  (cid,80,294,'production','[TOEFL Writing — Final 200 words] Write a concluding synthesis on what the accumulated evidence has established about a major social challenge.','',NULL,'The accumulated evidence reviewed in this essay has established several things clearly and left others genuinely uncertain, and intellectual honesty requires attending to both. What has been established clearly is that the problem is real, is consequential, disproportionately affects the most vulnerable members of society, and is not self-correcting — without deliberate intervention, it persists and often worsens. The evidence has also established that effective interventions exist: programs and policies have been identified that produce meaningful and lasting improvements for the populations they serve, and these findings have been replicated across diverse contexts with sufficient consistency to support confidence in their validity. What has not been established with equal clarity is the optimal design of those interventions for different contexts, the mechanisms through which they produce their effects, and the conditions under which they can be taken to scale without losing effectiveness. The field has also not yet resolved important questions about the cost-effectiveness of different approaches relative to each other and relative to investments in other social priorities. These remaining uncertainties are genuine, but they should not be allowed to obscure what the evidence has made clear: that the problem is solvable, that solutions exist, and that the primary barriers to progress are not epistemic but political — not a lack of knowledge about what to do, but a lack of will to do it.','hard')

